"use client";

import type React from "react";
import { useState, useCallback, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
  Sparkles,
  Loader2,
  ImagePlus,
  Gavel,
  DollarSign,
  Info,
  Check,
  ChevronRight,
  ChevronLeft,
  Package,
  Disc3,
  AlertCircle,
  CheckCircle2,
  ArrowRight,
  X,
  CreditCard,
  Music,
} from "lucide-react";
import { genres, conditions } from "@/lib/mock-data";
import { motion, AnimatePresence } from "motion/react";
import { DashboardBottomNav } from "@/components/dashboard-bottom-nav";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import type { VinylAnalysis } from "@/lib/types";
import { ProtectedAIFeature } from "@/components/protected-ai-feature";
import { CollectionSelector } from "@/components/dashboard/collection-selector";
import type { Vinyl } from "@/lib/db/schema";

type PricingType = "fixed" | "auction";
type RecordType = "sealed" | "used" | null;
type WizardStep = "source" | "type" | "images" | "review";
type SourceType = "new" | "collection";

interface AISuggestion {
  field: string;
  value: string | number;
  accepted: boolean;
}

export default function NewListingPage() {
  // Wizard state
  const [wizardStep, setWizardStep] = useState<WizardStep>("source");
  const [sourceType, setSourceType] = useState<SourceType>("new");
  const [selectedCollectionItem, setSelectedCollectionItem] = useState<Vinyl | null>(null);
  const [recordType, setRecordType] = useState<RecordType>(null);

  // AI analysis state
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState<VinylAnalysis | null>(null);

  // Form state
  const [title, setTitle] = useState("");
  const [artist, setArtist] = useState("");
  const [genre, setGenre] = useState("");
  const [year, setYear] = useState("");
  const [condition, setCondition] = useState("");
  const [sleeveCondition, setSleeveCondition] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [quantity, setQuantity] = useState("1");

  // Pricing type state
  const [pricingType, setPricingType] = useState<PricingType>("fixed");

  // Auction state
  const [startingBid, setStartingBid] = useState("");
  const [reservePrice, setReservePrice] = useState("");
  const [buyItNowPrice, setBuyItNowPrice] = useState("");
  const [auctionDuration, setAuctionDuration] = useState("7");
  const [enableBuyItNow, setEnableBuyItNow] = useState(false);
  const [enableReserve, setEnableReserve] = useState(false);

  // Image state
  const [frontCover, setFrontCover] = useState<string | null>(null);
  const [backCover, setBackCover] = useState<string | null>(null);
  const [vinylFront, setVinylFront] = useState<string | null>(null);
  const [vinylBack, setVinylBack] = useState<string | null>(null);

  // Track which AI suggestions have been accepted
  const [acceptedSuggestions, setAcceptedSuggestions] = useState<Set<string>>(new Set());

  // Stripe Connect status
  const [stripeConnectStatus, setStripeConnectStatus] = useState<{
    hasAccount: boolean;
    status: string | null;
    accountId: string | null;
    isSeller: boolean;
  } | null>(null);
  const [isCheckingStripe, setIsCheckingStripe] = useState(true);
  const router = useRouter();

  // Check Stripe Connect status on mount
  useEffect(() => {
    const checkStripe = async () => {
      try {
        const res = await fetch("/api/stripe/connect/check");
        if (res.ok) {
          const data = await res.json();
          setStripeConnectStatus(data);
        }
      } catch (error) {
        console.error("Error checking Stripe:", error);
      } finally {
        setIsCheckingStripe(false);
      }
    };
    checkStripe();
  }, []);

  // Prefill form when collection item is selected
  useEffect(() => {
    if (selectedCollectionItem) {
      setTitle(selectedCollectionItem.title);
      setArtist(selectedCollectionItem.artist);
      setGenre(selectedCollectionItem.genre);
      setYear(selectedCollectionItem.year?.toString() || "");
      setCondition(selectedCollectionItem.condition);
      setSleeveCondition(selectedCollectionItem.sleeveCondition || "");
      setDescription(selectedCollectionItem.description || "");
      
      const images = selectedCollectionItem.images ? JSON.parse(selectedCollectionItem.images) : [];
      if (images.length > 0) {
        const frontCoverImg = images.find((img: any) => img.type === "front_cover");
        const backCoverImg = images.find((img: any) => img.type === "back_cover");
        if (frontCoverImg) setFrontCover(frontCoverImg.url);
        if (backCoverImg) setBackCover(backCoverImg.url);
      }

      setRecordType(selectedCollectionItem.type === "new" ? "sealed" : "used");
      setWizardStep("review");
    }
  }, [selectedCollectionItem]);

  const showStripeBanner =
    stripeConnectStatus?.isSeller &&
    (!stripeConnectStatus.hasAccount || stripeConnectStatus.status !== "active");

  const handleImageUpload = (type: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Create object URL for preview
    const url = URL.createObjectURL(file);
    if (type === "frontCover") setFrontCover(url);
    if (type === "backCover") setBackCover(url);
    if (type === "vinylFront") setVinylFront(url);
    if (type === "vinylBack") setVinylBack(url);

    // TODO: Upload to blob storage and get permanent URL
  };

  const canProceedToAnalysis = () => {
    if (recordType === "sealed") {
      return frontCover && backCover;
    }
    return frontCover && backCover && vinylFront && vinylBack;
  };

  const handleAnalyzeWithAI = async () => {
    if (!canProceedToAnalysis()) return;

    setIsAnalyzing(true);
    setAnalysisError(null);

    try {
      const imageUrls = [frontCover, backCover];
      if (recordType === "used") {
        imageUrls.push(vinylFront, vinylBack);
      }

      const response = await fetch("/api/analyze-vinyl", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          imageUrls: imageUrls.filter(Boolean),
          isSealed: recordType === "sealed",
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to analyze images");
      }

      const analysis: VinylAnalysis = await response.json();
      setAiAnalysis(analysis);

      // Pre-fill form with AI suggestions
      setTitle(analysis.title);
      setArtist(analysis.artist);
      setGenre(analysis.genre);
      setYear(analysis.year);
      setCondition(analysis.condition.overall);
      setSleeveCondition(analysis.condition.sleeveCondition);
      setDescription(analysis.description);
      setPrice(analysis.priceEstimate.suggested.toString());

      // Mark all as accepted initially
      setAcceptedSuggestions(
        new Set(["title", "artist", "genre", "year", "condition", "sleeveCondition", "description", "price"]),
      );

      // Move to review step
      setWizardStep("review");
    } catch (error) {
      console.error("Analysis error:", error);
      setAnalysisError("Failed to analyze images. Please try again or continue with manual entry.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAcceptSuggestion = (field: string) => {
    setAcceptedSuggestions((prev) => new Set([...prev, field]));
  };

  const handleRejectSuggestion = (field: string) => {
    setAcceptedSuggestions((prev) => {
      const newSet = new Set(prev);
      newSet.delete(field);
      return newSet;
    });
  };

  const renderStepIndicator = () => (
    <div className="flex items-center justify-center gap-2 mb-6">
      {["source", "type", "images", "review"].map((step, index) => {
        const stepNames = { source: "Source", type: "Type", images: "Images", review: "Review" };
        const isActive = wizardStep === step;
        const isCompleted = ["source", "type", "images", "review"].indexOf(wizardStep) > index;

        return (
          <React.Fragment key={step}>
            <div className="flex flex-col items-center">
              <div
                className={cn(
                  "w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-colors",
                  isActive
                    ? "bg-primary text-primary-foreground"
                    : isCompleted
                      ? "bg-primary/20 text-primary"
                      : "bg-muted text-muted-foreground",
                )}
              >
                {isCompleted ? <Check className="h-4 w-4" /> : index + 1}
              </div>
              <span className="text-xs mt-1 text-muted-foreground hidden sm:block">{stepNames[step as WizardStep]}</span>
            </div>
            {index < 3 && (
              <div
                className={cn(
                  "w-8 h-0.5 transition-colors",
                  isCompleted ? "bg-primary" : "bg-muted",
                )}
              />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );

  const renderSourceStep = () => (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      className="space-y-6"
    >
      <Card className="border-0 shadow-sm">
        <CardHeader className="p-4 sm:p-6">
          <CardTitle className="text-lg sm:text-xl">Choose Source</CardTitle>
          <CardDescription>Create a new listing or select from your collection</CardDescription>
        </CardHeader>
        <CardContent className="p-4 pt-0 sm:p-6 sm:pt-0 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Card
              className={cn(
                "cursor-pointer transition-all hover:shadow-md",
                sourceType === "new" ? "ring-2 ring-primary" : "",
              )}
              onClick={() => setSourceType("new")}
            >
              <CardContent className="p-6 text-center">
                <Package className="h-12 w-12 mx-auto mb-4 text-primary" />
                <h3 className="font-semibold mb-2">New Listing</h3>
                <p className="text-sm text-muted-foreground">
                  Create a brand new listing from scratch
                </p>
              </CardContent>
            </Card>
            <Card
              className={cn(
                "cursor-pointer transition-all hover:shadow-md",
                sourceType === "collection" ? "ring-2 ring-primary" : "",
              )}
              onClick={() => setSourceType("collection")}
            >
              <CardContent className="p-6 text-center">
                <Music className="h-12 w-12 mx-auto mb-4 text-primary" />
                <h3 className="font-semibold mb-2">From Collection</h3>
                <p className="text-sm text-muted-foreground">
                  List a record from your collection
                </p>
              </CardContent>
            </Card>
          </div>

          {sourceType === "collection" && (
            <div className="mt-6">
              <h3 className="font-medium mb-4">Select from Collection</h3>
              <CollectionSelector
                onSelect={(vinyl) => {
                  setSelectedCollectionItem(vinyl);
                }}
              />
            </div>
          )}

          <div className="flex justify-end gap-2 pt-4">
            <Button
              variant="outline"
              onClick={() => router.back()}
              className="rounded-full"
            >
              Cancel
            </Button>
            <Button
              onClick={() => {
                if (sourceType === "collection" && !selectedCollectionItem) {
                  alert("Please select a record from your collection");
                  return;
                }
                if (sourceType === "new") {
                  setWizardStep("type");
                } else {
                  // Collection item selected, skip to review
                  setWizardStep("review");
                }
              }}
              className="rounded-full"
              disabled={sourceType === "collection" && !selectedCollectionItem}
            >
              Continue
              <ChevronRight className="h-4 w-4 ml-2" />
            </Button>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );

  // ... (keep existing renderTypeStep, renderImagesStep, renderReviewStep functions)
  // For brevity, I'll include the key parts

  return (
    <div className="min-h-screen pb-24 md:pb-8">
      <div className="p-4 md:p-6 space-y-6 max-w-7xl mx-auto">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold tracking-tight">Create Listing</h1>
          <p className="text-muted-foreground">Add a new vinyl record to the marketplace</p>
        </div>

        {showStripeBanner && (
          <Card className="border-amber-200 bg-amber-50/50">
            <CardContent className="p-4 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <CreditCard className="h-5 w-5 text-amber-600" />
                <div>
                  <p className="font-medium text-sm">
                    {!stripeConnectStatus?.hasAccount
                      ? "Set up payments to create listings"
                      : "Complete your payment setup"}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    You need an active Stripe Connect account to receive payments
                  </p>
                </div>
              </div>
              <Button
                size="sm"
                onClick={async () => {
                  // Handle Stripe setup
                  try {
                    if (!stripeConnectStatus?.hasAccount) {
                      const accountRes = await fetch("/api/stripe/connect/create-account", {
                        method: "POST",
                      });
                      if (!accountRes.ok) throw new Error("Failed to create account");
                      const { accountId } = await accountRes.json();

                      const linkRes = await fetch("/api/stripe/connect/create-link", {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ accountId }),
                      });
                      if (!linkRes.ok) throw new Error("Failed to create link");
                      const { url } = await linkRes.json();
                      window.location.href = url;
                    } else {
                      const linkRes = await fetch("/api/stripe/connect/create-link", {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ accountId: stripeConnectStatus.accountId }),
                      });
                      if (!linkRes.ok) throw new Error("Failed to create link");
                      const { url } = await linkRes.json();
                      window.location.href = url;
                    }
                  } catch (error) {
                    alert("Failed to set up payments. Please try again.");
                  }
                }}
                className="rounded-full"
              >
                Set up payments
              </Button>
            </CardContent>
          </Card>
        )}

        {renderStepIndicator()}

        <AnimatePresence mode="wait">
          {wizardStep === "source" && renderSourceStep()}
          {/* Add other step renders here */}
        </AnimatePresence>
      </div>
      <DashboardBottomNav />
    </div>
  );
}
